#include <stdckdint.h>
#include <stddef.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct blocco_32 {
    alignas(32) uint8_t dati[20];
} blocco_32_t;

static alignas(max_align_t) unsigned char buf_max[128];
static blocco_32_t arr_32[3];

static bool e_potenza_di_due(size_t a) {
    return a != 0 && (a & (a - 1)) == 0;
}

static bool arrotonda_allineamento(size_t n, size_t allin, size_t *out) {
    if (!e_potenza_di_due(allin) || out == nullptr) {
        return false;
    }
    size_t somma = 0;
    if (ckd_add(&somma, n, allin - 1)) {
        return false;
    }
    *out = somma & ~(allin - 1);
    return true;
}

static bool puntatore_allineato(const void *p, size_t allin) {
    if (p == nullptr || !e_potenza_di_due(allin)) {
        return false;
    }
    return ((uintptr_t)p & (uintptr_t)(allin - 1)) == 0;
}

static bool gestisci_layout(size_t k) {
    size_t offset = 0, pad_interno = 0, max_allin = 1;
    char riga[128], extra = '\0';
    for (size_t i = 0; i < k; ++i) {
        size_t dim = 0, allin = 0;
        if (fgets(riga, (int)sizeof(riga), stdin) == nullptr ||
            sscanf(riga, "%zu %zu %c", &dim, &allin, &extra) != 2 ||
            dim == 0 || !e_potenza_di_due(allin)) {
            return false;
        }
        size_t off_allin = 0, nuovo_off = 0;
        if (!arrotonda_allineamento(offset, allin, &off_allin) ||
            ckd_add(&nuovo_off, off_allin, dim)) {
            return false;
        }
        size_t pad = off_allin - offset;
        pad_interno += pad;
        printf("  campo %zu: offset=%zu dim=%zu allin=%zu pad=%zu\n",
               i, off_allin, dim, allin, pad);
        offset = nuovo_off;
        if (allin > max_allin) {
            max_allin = allin;
        }
    }
    size_t dim_tot = 0;
    if (!arrotonda_allineamento(offset, max_allin, &dim_tot)) {
        return false;
    }
    printf("LAYOUT(%zu): dim=%zu allin=%zu pad_interno=%zu pad_coda=%zu\n",
           k, dim_tot, max_allin, pad_interno, dim_tot - offset);
    return true;
}

int main(void) {
    char riga[128], cmd[24], extra = '\0';
    while (fgets(riga, (int)sizeof(riga), stdin) != nullptr) {
        if (sscanf(riga, "%23s", cmd) != 1) { continue; }
        size_t dim = 0, allin = 0, ris = 0;
        if (strcmp(cmd, "ALIGN") == 0 && sscanf(riga, "ALIGN %zu %zu %c", &dim, &allin, &extra) == 2) {
            if (arrotonda_allineamento(dim, allin, &ris)) {
                printf("ALIGN(%zu, %zu) = %zu\n", dim, allin, ris);
            } else {
                printf("ALIGN(%zu, %zu) = ERRORE\n", dim, allin);
            }
        } else if (strcmp(cmd, "ALIGN_MAX") == 0 && sscanf(riga, "ALIGN_MAX %zu %c", &allin, &extra) == 1) {
            bool ok = arrotonda_allineamento(SIZE_MAX, allin, &ris);
            printf("ALIGN(SIZE_MAX, %zu) = %s\n", allin, ok ? "OK" : "ERRORE");
        } else if (strcmp(cmd, "LAYOUT") == 0 && sscanf(riga, "LAYOUT %zu %c", &dim, &extra) == 1 && dim <= 16) {
            if (!gestisci_layout(dim)) { return EXIT_FAILURE; }
        } else if (strcmp(cmd, "CHECK_STATIC") == 0 && sscanf(riga, "CHECK_STATIC %c", &extra) != 1) {
            bool max_ok = puntatore_allineato(buf_max, alignof(max_align_t));
            bool arr_ok = true;
            for (size_t i = 0; i < 3; ++i) {
                if (!puntatore_allineato(&arr_32[i], 32)) { arr_ok = false; }
            }
            printf("CHECK_STATIC: max_align_ok=%d align32=%zu sizeof32=%zu array_ok=%d\n",
                   max_ok ? 1 : 0, alignof(blocco_32_t), sizeof(blocco_32_t), arr_ok ? 1 : 0);
        } else {
            fprintf(stderr, "Errore: comando non valido.\n");
            return EXIT_FAILURE;
        }
    }
    return EXIT_SUCCESS;
}

