#include "arena_st.h"
#include <stdckdint.h>
#include <stdint.h>

static bool potenza_di_due(size_t a) {
    return a != 0 && (a & (a - 1)) == 0;
}

bool arena_init(arena_t *a, void *buffer, size_t cap) {
    if (a == nullptr || buffer == nullptr || cap == 0) {
        return false;
    }
    if (((uintptr_t)buffer & (uintptr_t)(alignof(max_align_t) - 1)) != 0) {
        return false;
    }
    a->base = buffer;
    a->cap = cap;
    a->usati = 0;
    a->picco = 0;
    return true;
}

void *arena_alloca_allineato(arena_t *a, size_t dim, size_t allin) {
    if (a == nullptr || a->base == nullptr || dim == 0 || !potenza_di_due(allin)) {
        return nullptr;
    }
    uintptr_t curr = (uintptr_t)(a->base + a->usati);
    size_t resto = (size_t)(curr & (uintptr_t)(allin - 1));
    size_t pad = (resto == 0) ? 0 : (allin - resto);
    size_t inizio = 0, fine = 0;
    if (ckd_add(&inizio, a->usati, pad) || ckd_add(&fine, inizio, dim) || fine > a->cap) {
        return nullptr;
    }
    a->usati = fine;
    if (a->usati > a->picco) {
        a->picco = a->usati;
    }
    return a->base + inizio;
}

void *arena_alloca(arena_t *a, size_t dim) {
    return arena_alloca_allineato(a, dim, alignof(max_align_t));
}

size_t arena_marca(const arena_t *a) {
    return (a != nullptr) ? a->usati : 0;
}

bool arena_ripristina(arena_t *a, size_t marca) {
    if (a == nullptr || marca > a->usati) {
        return false;
    }
    a->usati = marca;
    return true;
}

void arena_reset(arena_t *a) {
    if (a != nullptr) {
        a->usati = 0;
    }
}

