#include <string.h>
#include "arena_st.h"

static_assert(64 >= alignof(max_align_t));
static alignas(64) unsigned char mem_arena[256];

int main(void) {
    arena_t arena = {};
    if (!arena_init(&arena, mem_arena, sizeof(mem_arena))) {
        return EXIT_FAILURE;
    }
    size_t marche[8] = {};
    size_t n_marche = 0;
    char riga[128], cmd[24], extra = '\0';
    while (fgets(riga, (int)sizeof(riga), stdin) != nullptr) {
        if (sscanf(riga, "%23s", cmd) != 1) { continue; }
        size_t dim = 0, allin = 0;
        if (strcmp(cmd, "ALLOC") == 0 && sscanf(riga, "ALLOC %zu %zu %c", &dim, &allin, &extra) == 2) {
            void *p = arena_alloca_allineato(&arena, dim, allin);
            if (p != nullptr) {
                bool ok = ((uintptr_t)p & (uintptr_t)(allin - 1)) == 0;
                memset(p, 0x5A, dim);
                printf("ALLOC(%zu, %zu): OK usati=%zu allin_ok=%d\n", dim, allin, arena.usati, ok ? 1 : 0);
            } else {
                printf("ALLOC(%zu, %zu): OOM\n", dim, allin);
            }
        } else if (strcmp(cmd, "ALLOC_DEF") == 0 && sscanf(riga, "ALLOC_DEF %zu %c", &dim, &extra) == 1) {
            void *p = arena_alloca(&arena, dim);
            if (p != nullptr) {
                bool ok = ((uintptr_t)p & (uintptr_t)(alignof(max_align_t) - 1)) == 0;
                memset(p, 0x3C, dim);
                printf("ALLOC_DEF(%zu): OK allin_ok=%d\n", dim, ok ? 1 : 0);
            } else {
                printf("ALLOC_DEF(%zu): OOM\n", dim);
            }
        } else if (strcmp(cmd, "MARK") == 0 && sscanf(riga, "MARK %c", &extra) != 1) {
            if (n_marche >= 8) { return EXIT_FAILURE; }
            marche[n_marche++] = arena_marca(&arena);
            printf("MARK #%zu: pos=%zu\n", n_marche, marche[n_marche - 1]);
        } else if (strcmp(cmd, "RESTORE") == 0 && sscanf(riga, "RESTORE %c", &extra) != 1) {
            if (n_marche == 0) {
                printf("RESTORE: VUOTA\n");
            } else {
                arena_ripristina(&arena, marche[--n_marche]);
                printf("RESTORE: OK usati=%zu\n", arena.usati);
            }
        } else if (strcmp(cmd, "RESET") == 0 && sscanf(riga, "RESET %c", &extra) != 1) {
            arena_reset(&arena);
            n_marche = 0;
            printf("RESET: usati=%zu\n", arena.usati);
        } else if (strcmp(cmd, "STATS") == 0 && sscanf(riga, "STATS %c", &extra) != 1) {
            printf("STATS: usati=%zu picco=%zu cap=%zu\n", arena.usati, arena.picco, arena.cap);
        } else {
            fprintf(stderr, "Errore: comando non valido.\n");
            return EXIT_FAILURE;
        }
    }
    return EXIT_SUCCESS;
}

