#include "pool_blocchi.h"
#include <stdckdint.h>
#include <stdint.h>
#include <stdlib.h>
#include <string.h>

struct pool {
    unsigned char *memoria;
    uint8_t *occupato;
    void *testa_libera;
    size_t passo;
    size_t n_blocchi;
    size_t n_occupati;
    size_t picco;
};

pool_t *pool_crea(size_t dim_blocco, size_t n_blocchi) {
    if (dim_blocco == 0 || n_blocchi == 0) { return nullptr; }
    size_t min_dim = (dim_blocco < sizeof(void *)) ? sizeof(void *) : dim_blocco;
    size_t allin = alignof(max_align_t);
    size_t somma = 0, tot_byte = 0;
    if (ckd_add(&somma, min_dim, allin - 1)) { return nullptr; }
    size_t passo = somma & ~(allin - 1);
    if (ckd_mul(&tot_byte, n_blocchi, passo)) { return nullptr; }
    pool_t *p = calloc(1, sizeof(*p));
    if (p == nullptr) { return nullptr; }
    p->memoria = malloc(tot_byte);
    p->occupato = calloc(n_blocchi, sizeof(*p->occupato));
    if (p->memoria == nullptr || p->occupato == nullptr) {
        free(p->memoria); free(p->occupato); free(p);
        return nullptr;
    }
    p->passo = passo;
    p->n_blocchi = n_blocchi;
    for (size_t i = 0; i < n_blocchi; ++i) {
        void *prox = (i + 1 < n_blocchi) ? (void *)(p->memoria + (i + 1) * passo) : nullptr;
        memcpy(p->memoria + i * passo, &prox, sizeof(prox));
    }
    p->testa_libera = p->memoria;
    return p;
}

void pool_distruggi(pool_t *p) {
    if (p == nullptr) { return; }
    free(p->memoria);
    free(p->occupato);
    free(p);
}

void *pool_alloca(pool_t *p) {
    if (p == nullptr || p->testa_libera == nullptr) { return nullptr; }
    void *blocco = p->testa_libera;
    void *prox = nullptr;
    memcpy(&prox, blocco, sizeof(prox));
    p->testa_libera = prox;
    size_t idx = (size_t)((unsigned char *)blocco - p->memoria) / p->passo;
    p->occupato[idx] = 1;
    ++p->n_occupati;
    if (p->n_occupati > p->picco) { p->picco = p->n_occupati; }
    return blocco;
}

pool_esito_t pool_libera(pool_t *p, void *ptr) {
    if (p == nullptr || ptr == nullptr) { return POOL_ERR_NULLO; }
    uintptr_t addr = (uintptr_t)ptr;
    uintptr_t base = (uintptr_t)p->memoria;
    uintptr_t fine = base + p->n_blocchi * p->passo;
    if (addr < base || addr >= fine || ((addr - base) % p->passo) != 0) {
        return POOL_ERR_FUORI_POOL;
    }
    size_t idx = (size_t)(addr - base) / p->passo;
    if (p->occupato[idx] == 0) { return POOL_ERR_DOPPIA_FREE; }
    p->occupato[idx] = 0;
    memcpy(ptr, &p->testa_libera, sizeof(p->testa_libera));
    p->testa_libera = ptr;
    --p->n_occupati;
    return POOL_OK;
}

size_t pool_liberi(const pool_t *p) { return (p != nullptr) ? (p->n_blocchi - p->n_occupati) : 0; }
size_t pool_occupati(const pool_t *p) { return (p != nullptr) ? p->n_occupati : 0; }
size_t pool_picco(const pool_t *p) { return (p != nullptr) ? p->picco : 0; }
size_t pool_capacita(const pool_t *p) { return (p != nullptr) ? p->n_blocchi : 0; }

