#include <inttypes.h>
#include <stddef.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include "pool_blocchi.h"

typedef struct sessione {
    uint32_t id;
    int64_t punti;
    char tag[12];
} sessione_t;

static const char *nome_esito(pool_esito_t e) {
    switch (e) {
        case POOL_OK: return "OK";
        case POOL_ERR_NULLO: return "NULLO";
        case POOL_ERR_FUORI_POOL: return "FUORI_POOL";
        case POOL_ERR_DOPPIA_FREE: return "DOPPIA_FREE";
        default: return "ERRORE";
    }
}

int main(void) {
    pool_t *pool = nullptr;
    sessione_t *slots[16] = {};
    char riga[128], cmd[24], tag[12], extra = '\0';
    while (fgets(riga, (int)sizeof(riga), stdin) != nullptr) {
        if (sscanf(riga, "%23s", cmd) != 1) { continue; }
        size_t n = 0, idx = 0;
        unsigned long id = 0;
        long long punti = 0;
        if (strcmp(cmd, "INIT") == 0 && sscanf(riga, "INIT %zu %c", &n, &extra) == 1 && n >= 1 && n <= 16) {
            pool_distruggi(pool);
            memset(slots, 0, sizeof(slots));
            pool = pool_crea(sizeof(sessione_t), n);
            if (pool == nullptr) { return EXIT_FAILURE; }
            printf("INIT: cap=%zu\n", pool_capacita(pool));
        } else if (strcmp(cmd, "NEW") == 0 && pool != nullptr &&
                   sscanf(riga, "NEW %zu %lu %lld %11s %c", &idx, &id, &punti, tag, &extra) == 4 && idx < 16) {
            sessione_t *s = pool_alloca(pool);
            if (s == nullptr) {
                printf("NEW[%zu]: PIENO\n", idx);
            } else {
                s->id = (uint32_t)id;
                s->punti = (int64_t)punti;
                snprintf(s->tag, sizeof(s->tag), "%s", tag);
                slots[idx] = s;
                bool ok = ((uintptr_t)s & (uintptr_t)(alignof(sessione_t) - 1)) == 0;
                printf("NEW[%zu]: OK allin_ok=%d\n", idx, ok ? 1 : 0);
            }
        } else if (strcmp(cmd, "SHOW") == 0 && sscanf(riga, "SHOW %zu %c", &idx, &extra) == 1 && idx < 16 && slots[idx] != nullptr) {
            printf("SHOW[%zu]: id=%" PRIu32 " punti=%" PRId64 " tag=%s\n", idx, slots[idx]->id, slots[idx]->punti, slots[idx]->tag);
        } else if (strcmp(cmd, "FREE") == 0 && pool != nullptr && sscanf(riga, "FREE %zu %c", &idx, &extra) == 1 && idx < 16) {
            printf("FREE[%zu]: %s\n", idx, nome_esito(pool_libera(pool, slots[idx])));
        } else if (strcmp(cmd, "FREE_BAD") == 0 && pool != nullptr && sscanf(riga, "FREE_BAD %c", &extra) != 1) {
            int locale = 42;
            pool_esito_t e1 = pool_libera(pool, nullptr);
            pool_esito_t e2 = pool_libera(pool, &locale);
            const char *s3 = "SALTATO";
            if (slots[0] != nullptr) {
                s3 = nome_esito(pool_libera(pool, (unsigned char *)slots[0] + 1));
            }
            printf("FREE_BAD: null=%s stack=%s disallin=%s\n", nome_esito(e1), nome_esito(e2), s3);
        } else if (strcmp(cmd, "STATS") == 0 && pool != nullptr && sscanf(riga, "STATS %c", &extra) != 1) {
            printf("STATS: liberi=%zu occupati=%zu tot=%zu picco=%zu\n",
                   pool_liberi(pool), pool_occupati(pool), pool_capacita(pool), pool_picco(pool));
        } else {
            pool_distruggi(pool);
            return EXIT_FAILURE;
        }
    }
    pool_distruggi(pool);
    return EXIT_SUCCESS;
}

