#include "alloc_libera.h"
#include <stdckdint.h>
#include <stdlib.h>

static constexpr size_t ALLIN_FL = (alignof(max_align_t) > 16) ? alignof(max_align_t) : 16;
static constexpr uint32_t MAGICO_FL = 0x464C4F4BU;

typedef struct blocco_fl {
    alignas(ALLIN_FL) size_t dim;
    struct blocco_fl *prox;
    uint32_t magico;
    bool libero;
} blocco_fl_t;

static_assert(sizeof(blocco_fl_t) % ALLIN_FL == 0);

struct alloc_fl {
    unsigned char *memoria;
    size_t cap;
    blocco_fl_t *testa;
};

alloc_fl_t *fl_crea(size_t cap_byte) {
    size_t cap = cap_byte & ~(ALLIN_FL - 1);
    if (cap < sizeof(blocco_fl_t) + ALLIN_FL) { return nullptr; }
    alloc_fl_t *a = calloc(1, sizeof(*a));
    if (a == nullptr) { return nullptr; }
    a->memoria = malloc(cap);
    if (a->memoria == nullptr) { free(a); return nullptr; }
    a->cap = cap;
    a->testa = (blocco_fl_t *)(void *)a->memoria;
    a->testa->dim = cap - sizeof(blocco_fl_t);
    a->testa->prox = nullptr;
    a->testa->magico = MAGICO_FL;
    a->testa->libero = true;
    return a;
}

void fl_distruggi(alloc_fl_t *a) {
    if (a == nullptr) { return; }
    free(a->memoria);
    free(a);
}

void *fl_alloca(alloc_fl_t *a, size_t dim) {
    if (a == nullptr || dim == 0) { return nullptr; }
    size_t somma = 0;
    if (ckd_add(&somma, dim, ALLIN_FL - 1)) { return nullptr; }
    size_t req = somma & ~(ALLIN_FL - 1);
    for (blocco_fl_t *cur = a->testa; cur != nullptr; cur = cur->prox) {
        if (!cur->libero || cur->dim < req) { continue; }
        unsigned char *payload = (unsigned char *)cur + sizeof(blocco_fl_t);
        if (cur->dim >= req + sizeof(blocco_fl_t) + ALLIN_FL) {
            blocco_fl_t *resto = (blocco_fl_t *)(void *)(payload + req);
            resto->dim = cur->dim - req - sizeof(blocco_fl_t);
            resto->prox = cur->prox;
            resto->magico = MAGICO_FL;
            resto->libero = true;
            cur->dim = req;
            cur->prox = resto;
        }
        cur->libero = false;
        return payload;
    }
    return nullptr;
}

bool fl_libera(alloc_fl_t *a, void *ptr) {
    if (a == nullptr || ptr == nullptr) { return false; }
    blocco_fl_t *trovato = nullptr;
    for (blocco_fl_t *cur = a->testa; cur != nullptr; cur = cur->prox) {
        if ((void *)((unsigned char *)cur + sizeof(blocco_fl_t)) == ptr) {
            trovato = cur;
            break;
        }
    }
    if (trovato == nullptr || trovato->magico != MAGICO_FL || trovato->libero) { return false; }
    trovato->libero = true;
    blocco_fl_t *b = a->testa;
    while (b != nullptr && b->prox != nullptr) {
        if (b->libero && b->prox->libero) {
            b->dim += sizeof(blocco_fl_t) + b->prox->dim;
            b->prox = b->prox->prox;
        } else {
            b = b->prox;
        }
    }
    return true;
}

void fl_statistiche(const alloc_fl_t *a, fl_stats_t *st) {
    if (st == nullptr) { return; }
    *st = (fl_stats_t){};
    if (a == nullptr) { return; }
    for (const blocco_fl_t *c = a->testa; c != nullptr; c = c->prox) {
        ++st->blocchi_tot;
        if (c->libero) {
            ++st->blocchi_lib;
            st->byte_lib += c->dim;
            if (c->dim > st->max_blocco_lib) { st->max_blocco_lib = c->dim; }
        } else {
            ++st->blocchi_occ;
