static bool gestisci_new(alloc_fl_t *al, serie_dati_t **handle, const char *riga) {
    size_t slot = 0, k = 0;
    unsigned long id = 0;
    int pos = 0;
    if (sscanf(riga, "NEW %zu %lu %zu%n", &slot, &id, &k, &pos) != 3 || slot >= 16 || k > 32) {
        return false;
    }
    size_t byte_arr = 0, byte_tot = 0;
    if (ckd_mul(&byte_arr, k, sizeof(int32_t)) || ckd_add(&byte_tot, offsetof(serie_dati_t, valori), byte_arr)) {
        return false;
    }
    int32_t tmp[32] = {};
    const char *p = riga + pos;
    for (size_t i = 0; i < k; ++i) {
        long v = 0;
        int avanz = 0;
        if (sscanf(p, "%ld%n", &v, &avanz) != 1 || v < INT32_MIN || v > INT32_MAX) { return false; }
        tmp[i] = (int32_t)v;
        p += avanz;
    }
    serie_dati_t *s = fl_alloca(al, byte_tot);
    if (s == nullptr) {
        printf("NEW[%zu]: OOM\n", slot);
        return true;
    }
    s->id = (uint32_t)id;
    s->len = k;
    if (k > 0) { memcpy(s->valori, tmp, k * sizeof(int32_t)); }
    handle[slot] = s;
    bool ok = ((uintptr_t)s & (uintptr_t)(alignof(serie_dati_t) - 1)) == 0;
    printf("NEW[%zu]: OK id=%" PRIu32 " len=%zu allin_ok=%d\n", slot, s->id, s->len, ok ? 1 : 0);
    return true;
}

int main(void) {
    alloc_fl_t *al = nullptr;
    serie_dati_t *handle[16] = {};
    char riga[256], cmd[16], extra = '\0';
    while (fgets(riga, (int)sizeof(riga), stdin) != nullptr) {
        if (sscanf(riga, "%15s", cmd) != 1) { continue; }
        size_t n = 0;
        if (strcmp(cmd, "INIT") == 0 && sscanf(riga, "INIT %zu %c", &n, &extra) == 1) {
            fl_distruggi(al);
            memset(handle, 0, sizeof(handle));
            al = fl_crea(n);
            if (al == nullptr) { return EXIT_FAILURE; }
            printf("INIT: cap=%zu\n", n);
        } else if (strcmp(cmd, "NEW") == 0 && al != nullptr) {
            if (!gestisci_new(al, handle, riga)) { fl_distruggi(al); return EXIT_FAILURE; }
        } else if (strcmp(cmd, "SUM") == 0 && sscanf(riga, "SUM %zu %c", &n, &extra) == 1 && n < 16 && handle[n] != nullptr) {
            int64_t somma = 0;
            for (size_t i = 0; i < handle[n]->len; ++i) { somma += handle[n]->valori[i]; }
            printf("SUM[%zu]: id=%" PRIu32 " somma=%" PRId64 "\n", n, handle[n]->id, somma);
        } else if (strcmp(cmd, "FREE") == 0 && al != nullptr && sscanf(riga, "FREE %zu %c", &n, &extra) == 1 && n < 16) {
            printf("FREE[%zu]: %s\n", n, fl_libera(al, handle[n]) ? "OK" : "ERRORE");
        } else if (strcmp(cmd, "MAP") == 0 && al != nullptr && sscanf(riga, "MAP %c", &extra) != 1) {
            fl_stats_t st = {};
            fl_statistiche(al, &st);
            printf("MAP: blocchi=%zu occ=%zu lib=%zu byte_occ=%zu byte_lib=%zu max_lib=%zu\n",
                   st.blocchi_tot, st.blocchi_occ, st.blocchi_lib, st.byte_occ, st.byte_lib, st.max_blocco_lib);
        } else {
            fl_distruggi(al); return EXIT_FAILURE;
        }
    }
    fl_distruggi(al);
    return EXIT_SUCCESS;
}

