#include "mem_diag.h"
#include <stdckdint.h>
#include <stdlib.h>
#include <string.h>

static constexpr size_t ALLIN_GUARD = (alignof(max_align_t) > 16) ? alignof(max_align_t) : 16;
static constexpr size_t MAX_RECORD = 64;
static constexpr unsigned char CAN_SX = 0xA5U, CAN_DX = 0x5AU, VEL_A = 0xAAU, VEL_F = 0xDDU;

static_assert(sizeof(float) == sizeof(uint32_t));

typedef struct rec_blocco {
    uintptr_t chiave;
    unsigned char *grezzo;
    size_t dim;
    bool attivo;
} rec_blocco_t;

struct diag_ctx {
    rec_blocco_t rec[MAX_RECORD];
    size_t n_rec;
};

diag_ctx_t *diag_crea(void) { return calloc(1, sizeof(diag_ctx_t)); }

void diag_distruggi(diag_ctx_t *ctx) {
    if (ctx == nullptr) { return; }
    for (size_t i = 0; i < ctx->n_rec; ++i) {
        if (ctx->rec[i].attivo) { free(ctx->rec[i].grezzo); }
    }
    free(ctx);
}

void *diag_alloca(diag_ctx_t *ctx, size_t dim) {
    if (ctx == nullptr || dim == 0 || ctx->n_rec >= MAX_RECORD) { return nullptr; }
    size_t tmp = 0, tot = 0;
    if (ckd_add(&tmp, dim, ALLIN_GUARD) || ckd_add(&tot, tmp, ALLIN_GUARD)) { return nullptr; }
    unsigned char *grezzo = malloc(tot);
    if (grezzo == nullptr) { return nullptr; }
    memset(grezzo, CAN_SX, ALLIN_GUARD);
    memset(grezzo + ALLIN_GUARD, VEL_A, dim);
    memset(grezzo + ALLIN_GUARD + dim, CAN_DX, ALLIN_GUARD);
    unsigned char *payload = grezzo + ALLIN_GUARD;
    ctx->rec[ctx->n_rec++] = (rec_blocco_t){.chiave = (uintptr_t)payload, .grezzo = grezzo, .dim = dim, .attivo = true};
    return payload;
}

static diag_esito_t controlla_rec(const rec_blocco_t *r) {
    if (!r->attivo) { return DIAG_ERR_GIA_LIBERATO; }
    bool sx_err = false, dx_err = false;
    for (size_t i = 0; i < ALLIN_GUARD; ++i) {
        if (r->grezzo[i] != CAN_SX) { sx_err = true; }
        if (r->grezzo[ALLIN_GUARD + r->dim + i] != CAN_DX) { dx_err = true; }
    }
    if (sx_err && dx_err) { return DIAG_ERR_ENTRAMBI; }
    if (sx_err) { return DIAG_ERR_UNDERFLOW; }
    if (dx_err) { return DIAG_ERR_OVERFLOW; }
    return DIAG_OK;
}

diag_esito_t diag_verifica(const diag_ctx_t *ctx, const void *ptr) {
    if (ctx == nullptr || ptr == nullptr) { return DIAG_ERR_SCONOSCIUTO; }
    uintptr_t k = (uintptr_t)ptr;
    for (size_t i = ctx->n_rec; i > 0; --i) {
        if (ctx->rec[i - 1].chiave == k) { return controlla_rec(&ctx->rec[i - 1]); }
    }
    return DIAG_ERR_SCONOSCIUTO;
}

diag_esito_t diag_libera(diag_ctx_t *ctx, void *ptr) {
    if (ctx == nullptr || ptr == nullptr) { return DIAG_ERR_SCONOSCIUTO; }
    uintptr_t k = (uintptr_t)ptr;
    for (size_t i = ctx->n_rec; i > 0; --i) {
        rec_blocco_t *r = &ctx->rec[i - 1];
        if (r->chiave == k) {
            diag_esito_t es = controlla_rec(r);
            if (r->attivo) {
                memset(r->grezzo + ALLIN_GUARD, VEL_F, r->dim);
                free(r->grezzo);
                r->grezzo = nullptr;
                r->attivo = false;
            }
            return es;
        }
    }
    return DIAG_ERR_SCONOSCIUTO;
}

void diag_report_leak(const diag_ctx_t *ctx, size_t *blocchi_attivi, size_t *byte_attivi) {
    size_t bl = 0, by = 0;
    if (ctx != nullptr) {
        for (size_t i = 0; i < ctx->n_rec; ++i) {
            if (ctx->rec[i].attivo) { ++bl; by += ctx->rec[i].dim; }
        }
    }
    if (blocchi_attivi != nullptr) { *blocchi_attivi = bl; }
    if (byte_attivi != nullptr) { *byte_attivi = by; }
}

const char *diag_esito_nome(diag_esito_t e) {
    switch (e) {
        case DIAG_OK: return "OK";
        case DIAG_ERR_SCONOSCIUTO: return "SCONOSCIUTO";
        case DIAG_ERR_GIA_LIBERATO: return "GIA_LIBERATO";
        case DIAG_ERR_UNDERFLOW: return "UNDERFLOW";
        case DIAG_ERR_OVERFLOW: return "OVERFLOW";
        case DIAG_ERR_ENTRAMBI: return "ENTRAMBI";
        default: return "ERRORE";
    }
}

uint32_t float_a_bit(float x) {
    uint32_t b = 0;
    memcpy(&b, &x, sizeof(b));
    return b;
}

float bit_a_float(uint32_t b) {
    float x = 0.0f;
    memcpy(&x, &b, sizeof(x));
    return x;
}

void combina_disgiunti(size_t n, float *restrict dst, const float *restrict a, const float *restrict b, float k) {
    for (size_t i = 0; i < n; ++i) {
        dst[i] = a[i] + k * b[i];
    }
}

