#include <inttypes.h>
#include <stddef.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include "mem_diag.h"

static bool gestisci_axpy(diag_ctx_t *ctx, const char *riga) {
    float k = 0.0f;
    size_t n = 0;
    int pos = 0;
    if (sscanf(riga, "AXPY %f %zu%n", &k, &n, &pos) != 2 || n == 0 || n > 16) { return false; }
    float *a = diag_alloca(ctx, n * sizeof(float));
    float *b = diag_alloca(ctx, n * sizeof(float));
    float *d = diag_alloca(ctx, n * sizeof(float));
    if (a == nullptr || b == nullptr || d == nullptr) { return false; }
    const char *p = riga + pos;
    for (size_t i = 0; i < n; ++i) { int av = 0; if (sscanf(p, "%f%n", &a[i], &av) != 1) { return false; } p += av; }
    for (size_t i = 0; i < n; ++i) { int av = 0; if (sscanf(p, "%f%n", &b[i], &av) != 1) { return false; } p += av; }
    combina_disgiunti(n, d, a, b, k);
    printf("AXPY:");
    for (size_t i = 0; i < n; ++i) { printf(" %.2f", (double)d[i]); }
    bool ok = (diag_libera(ctx, d) == DIAG_OK && diag_libera(ctx, b) == DIAG_OK && diag_libera(ctx, a) == DIAG_OK);
    printf(" (guardie=%s)\n", ok ? "OK" : "ERRORE");
    return true;
}

int main(void) {
    diag_ctx_t *ctx = diag_crea();
    if (ctx == nullptr) { return EXIT_FAILURE; }
    unsigned char *ptr[16] = {};
    size_t dim[16] = {};
    char riga[256], cmd[24], extra = '\0';
    while (fgets(riga, (int)sizeof(riga), stdin) != nullptr) {
        if (sscanf(riga, "%23s", cmd) != 1) { continue; }
        size_t id = 0, sz = 0;
        float fv = 0.0f;
        if (strcmp(cmd, "ALLOC") == 0 && sscanf(riga, "ALLOC %zu %zu %c", &id, &sz, &extra) == 2 && id < 16) {
            ptr[id] = diag_alloca(ctx, sz);
            dim[id] = sz;
            printf("ALLOC[%zu]: %s dim=%zu\n", id, (ptr[id] != nullptr) ? "OK" : "OOM", sz);
        } else if (strcmp(cmd, "CORROMPI_SX") == 0 && sscanf(riga, "CORROMPI_SX %zu %c", &id, &extra) == 1 && id < 16 && ptr[id] != nullptr) {
            ptr[id][-1] = 0xFFU;
            printf("CORROMPI_SX[%zu]: OK\n", id);
        } else if (strcmp(cmd, "CORROMPI_DX") == 0 && sscanf(riga, "CORROMPI_DX %zu %c", &id, &extra) == 1 && id < 16 && ptr[id] != nullptr) {
            ptr[id][dim[id]] = 0xFFU;
            printf("CORROMPI_DX[%zu]: OK\n", id);
        } else if (strcmp(cmd, "CHECK") == 0 && sscanf(riga, "CHECK %zu %c", &id, &extra) == 1 && id < 16) {
            printf("CHECK[%zu]: %s\n", id, diag_esito_nome(diag_verifica(ctx, ptr[id])));
        } else if (strcmp(cmd, "FREE") == 0 && sscanf(riga, "FREE %zu %c", &id, &extra) == 1 && id < 16) {
            printf("FREE[%zu]: %s\n", id, diag_esito_nome(diag_libera(ctx, ptr[id])));
        } else if (strcmp(cmd, "FBITS") == 0 && sscanf(riga, "FBITS %f %c", &fv, &extra) == 1) {
            uint32_t bits = float_a_bit(fv);
            uint32_t segno = (bits >> 31) & 1U, esp = (bits >> 23) & 0xFFU, mant = bits & 0x7FFFFFU;
            bool rt = (float_a_bit(bit_a_float(bits)) == bits);
            printf("FBITS %.2f: hex=0x%08" PRIx32 " segno=%" PRIu32 " esp=%" PRIu32 " mant=0x%06" PRIx32 " roundtrip=%s\n",
                   (double)fv, bits, segno, esp, mant, rt ? "OK" : "NO");
        } else if (strcmp(cmd, "AXPY") == 0) {
            if (!gestisci_axpy(ctx, riga)) { diag_distruggi(ctx); return EXIT_FAILURE; }
        } else if (strcmp(cmd, "LEAKS") == 0 && sscanf(riga, "LEAKS %c", &extra) != 1) {
            size_t bl = 0, by = 0;
            diag_report_leak(ctx, &bl, &by);
            printf("LEAKS: blocchi=%zu byte=%zu\n", bl, by);
        } else {
            diag_distruggi(ctx); return EXIT_FAILURE;
        }
    }
    diag_distruggi(ctx);
    return EXIT_SUCCESS;
}
